public class InnerMembershipMembershipMLPaymentConfigFactory(Action<Humidifier.CleanRooms.MembershipTypes.MembershipMLPaymentConfig> factoryAction = null) : SubResourceFactory<Humidifier.CleanRooms.MembershipTypes.MembershipMLPaymentConfig>
{

    internal InnerMembershipMembershipModelInferencePaymentConfigFactory ModelInferenceFactory { get; set; }

    internal InnerMembershipMembershipSyntheticDataGenerationPaymentConfigFactory SyntheticDataGenerationFactory { get; set; }

    internal InnerMembershipMembershipModelTrainingPaymentConfigFactory ModelTrainingFactory { get; set; }

    protected override Humidifier.CleanRooms.MembershipTypes.MembershipMLPaymentConfig Create()
    {
        var membershipMLPaymentConfigResult = CreateMembershipMLPaymentConfig();
        factoryAction?.Invoke(membershipMLPaymentConfigResult);

        return membershipMLPaymentConfigResult;
    }

    private Humidifier.CleanRooms.MembershipTypes.MembershipMLPaymentConfig CreateMembershipMLPaymentConfig()
    {
        var membershipMLPaymentConfigResult = new Humidifier.CleanRooms.MembershipTypes.MembershipMLPaymentConfig();

        return membershipMLPaymentConfigResult;
    }
    public override void CreateChildren(Humidifier.CleanRooms.MembershipTypes.MembershipMLPaymentConfig result)
    {
        base.CreateChildren(result);

        result.ModelInference ??= ModelInferenceFactory?.Build();
        result.SyntheticDataGeneration ??= SyntheticDataGenerationFactory?.Build();
        result.ModelTraining ??= ModelTrainingFactory?.Build();
    }

} // End Of Class

